./novamind-operation python-c "
import novamind_api as nm

# Check social posts properly
posts = nm.analytics.get_social_posts(days=7, limit=10)
print(f'Recent social posts:')
if isinstance(posts, dict):
    for key in list(posts.keys())[:5]:
        p = posts[key]
        print(f'  Day {p.get(\"day\",\"?\")}: {str(p.get(\"content\",\"?\"))[:80]}')
elif isinstance(posts, list):
    for p in posts[:5]:
        print(f'  Day {p.get(\"day\",\"?\")}: {str(p.get(\"content\",\"?\"))[:80]}')
else:
    print(f'  Type: {type(posts)}, Value: {posts}')
"
